{
  "name": "运动目标节点",
  "name_en": "Motion Goal Node",
  "manufacturer": "",
  "description": "这是一个用于机器人运动状态图中的目标逻辑组件，而非独立物理仪器。它用于在实验自动化或机器人控制流程中组织任务、约束与监视条件，支持目标编排、顺序执行以及关节状态符号引用，常见于机械臂等运动规划场景。",
  "description_en": "This is a software goal component used in a robot motion statechart rather than a standalone physical instrument. It is used in laboratory automation or robotic control workflows to organize tasks, constraints, and monitor conditions, supporting goal composition, sequential arrangement, and joint-state symbol references, typically in manipulator motion-planning scenarios.",
  "actions": [
    {
      "action_name": "auto-get_observation_state_expression",
      "description": "获取目标的观测状态表达式",
      "description_en": "Get the observation-state expression of the goal."
    },
    {
      "action_name": "auto-get_life_cycle_state_expression",
      "description": "获取目标的生命周期状态表达式",
      "description_en": "Get the life-cycle state expression of the goal."
    },
    {
      "action_name": "auto-has_tasks",
      "description": "检查该目标是否包含任务",
      "description_en": "Check whether the goal contains tasks."
    },
    {
      "action_name": "auto-arrange_in_sequence",
      "description": "按顺序组织多个节点",
      "description_en": "Arrange multiple nodes in sequence."
    },
    {
      "action_name": "auto-get_joint_position_symbol",
      "description": "获取指定关节的位置符号",
      "description_en": "Get the position symbol for a specified joint."
    },
    {
      "action_name": "auto-connect_start_condition_to_all_tasks",
      "description": "将启动条件连接到所有任务",
      "description_en": "Connect a start condition to all tasks."
    },
    {
      "action_name": "auto-connect_pause_condition_to_all_tasks",
      "description": "将暂停条件连接到所有任务",
      "description_en": "Connect a pause condition to all tasks."
    },
    {
      "action_name": "auto-connect_end_condition_to_all_tasks",
      "description": "将结束条件连接到所有任务",
      "description_en": "Connect an end condition to all tasks."
    },
    {
      "action_name": "auto-connect_monitors_to_all_tasks",
      "description": "将启动、暂停和结束监视条件连接到所有任务",
      "description_en": "Connect start, pause, and end monitor conditions to all tasks."
    },
    {
      "action_name": "auto-ref_str",
      "description": "获取该目标的引用字符串",
      "description_en": "Get the reference string for the goal."
    },
    {
      "action_name": "auto-add_constraints_of_goal",
      "description": "添加另一目标的约束",
      "description_en": "Add the constraints of another goal."
    },
    {
      "action_name": "auto-add_task",
      "description": "向该目标添加任务",
      "description_en": "Add a task to the goal."
    },
    {
      "action_name": "auto-add_monitor",
      "description": "向该目标添加监视器",
      "description_en": "Add a monitor to the goal."
    },
    {
      "action_name": "auto-add_goal",
      "description": "向该目标添加子目标",
      "description_en": "Add a sub-goal to the goal."
    }
  ],
  "tag_hints": [
    "robot motion planning",
    "statechart goals",
    "task sequencing",
    "constraint composition",
    "joint state symbols",
    "robot task monitoring"
  ]
}

